// Chain module: several rows in one blueprint, each row feeding the next.
//
//   feed ─▶ S S          row 0
//           M M
//           J J ─▶ S S   output line of row 0 is the feed line of row 1
//                  M M
//                  J J ─▶
//
// Rows are generated by row.ts and shifted so that the merger line of one row
// and the splitter line of the next lie on the same Y, the next row starting
// 4 m after the last merger (2 m belt between the ports). The whole layout is
// then centered on the 1 m grid. Only 'forward' output: products have to leave
// at the end where the next row begins.

import { generateRow, type RowRequest } from './row';
import type { Belt, Layout, Part } from './layout';
import { worldBoxes, type Vec3 } from './geometry';

export interface ChainStage {
  recipe: string;
  machines: number;
}

export type ChainRequest = Omit<RowRequest, 'recipe' | 'machines' | 'output'> & { stages: ChainStage[] };

const GAP = 4;

export function generateChain(req: ChainRequest): Layout {
  const feedDir = (req.feedFrom ?? 'left') === 'left' ? 1 : -1;
  const parts: Part[] = [];
  const belts: Belt[] = [];
  let prev: { merger: Part; tag: string } | undefined;

  req.stages.forEach((stage, k) => {
    const tag = String.fromCharCode(65 + k);
    const row = generateRow({ ...req, ...stage, output: 'forward' });
    const s0 = row.parts.find((p) => p.id === 'S0')!;
    let shift: Vec3 = { x: 0, y: 0, z: 0 };
    if (prev) {
      if (prev.merger.pos.z !== s0.pos.z) throw new Error(`port heights differ between ${prev.tag} and ${tag}`);
      shift = { x: prev.merger.pos.x + feedDir * GAP - s0.pos.x, y: prev.merger.pos.y - s0.pos.y, z: 0 };
    }
    const move = (v: Vec3): Vec3 => ({ x: v.x + shift.x, y: v.y + shift.y, z: v.z + shift.z });
    const ref = (r: Belt['fromPort']) => r && { part: tag + r.part, port: r.port };
    for (const p of row.parts) parts.push({ ...p, id: tag + p.id, pos: move(p.pos) });
    for (const b of row.belts) {
      // The next row takes its feed from the previous row's output line.
      if (prev && b.id === 'feed') continue;
      belts.push({ ...b, id: tag + b.id, from: move(b.from), to: move(b.to), fromPort: ref(b.fromPort), toPort: ref(b.toPort) });
    }
    const merger = parts.find((p) => p.id === `${tag}J${stage.machines - 1}`)!;
    if (prev) {
      const first = parts.find((p) => p.id === `${tag}S0`)!;
      belts.push({
        id: `${prev.tag}${tag}link`,
        cls: `Build_ConveyorBeltMk${req.beltTier}_C`,
        from: { ...prev.merger.pos, x: prev.merger.pos.x + feedDir },
        to: { ...first.pos, x: first.pos.x - feedDir },
        fromPort: { part: prev.merger.id, port: 'Output1' },
        toPort: { part: first.id, port: 'Input1' },
      });
    }
    prev = { merger, tag };
  });

  // Center the layout on the 1 m grid, measured on the building boxes and belt ends.
  const boxes = parts.flatMap((p) => worldBoxes(p.cls, p.pos, p.yaw));
  const xs = [...boxes.flatMap((b) => [b.min.x, b.max.x]), ...belts.flatMap((b) => [b.from.x, b.to.x])];
  const ys = [...boxes.flatMap((b) => [b.min.y, b.max.y]), ...belts.flatMap((b) => [b.from.y, b.to.y])];
  const dx = -Math.round((Math.min(...xs) + Math.max(...xs)) / 2);
  const dy = -Math.round((Math.min(...ys) + Math.max(...ys)) / 2);
  const center = (v: Vec3): Vec3 => ({ x: v.x + dx, y: v.y + dy, z: v.z });
  return {
    designer: req.designer,
    parts: parts.map((p) => ({ ...p, pos: center(p.pos) })),
    belts: belts.map((b) => ({ ...b, from: center(b.from), to: center(b.to) })),
  };
}
